import java.util.*;import java.nio.file.*;import java.util.jar.*;import java.io.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.commons.*;
public class Remap {
 public static void main(String[] a)throws Exception{
 Map<String,String> c=new HashMap<>(),f=new HashMap<>(),m=new HashMap<>();for(String l:Files.readAllLines(Path.of(a[1]))){String[] p=l.split("\t");if(p[0].equals("C"))c.put(p[1],p[2]);if(p[0].equals("F"))f.put(p[1]+"/"+p[2],p[3]);if(p[0].equals("M"))m.put(p[1]+"/"+p[2]+p[3],p[4]);}
 Map<String,ClassNode> nodes=new HashMap<>();try(JarFile j=new JarFile(a[0])){for(var e:Collections.list(j.entries()))if(e.getName().endsWith(".class")){ClassNode n=new ClassNode();new ClassReader(j.getInputStream(e)).accept(n,0);nodes.put(n.name,n);}}
 Remapper r=new Remapper(){String find(String owner,String key,Map<String,String> map,Set<String> seen){if(!seen.add(owner))return null;String v=map.get(owner+"/"+key);if(v!=null)return v;ClassNode n=nodes.get(owner);if(n!=null){if(n.superName!=null){v=find(n.superName,key,map,seen);if(v!=null)return v;}for(String i:n.interfaces){v=find(i,key,map,seen);if(v!=null)return v;}}return null;}
 public String mapInvokeDynamicMethodName(String name,String desc){try{String owner=Type.getReturnType(desc).getInternalName();ClassNode n=nodes.get(owner);if(n!=null)for(MethodNode method:n.methods)if(method.name.equals(name)&&(method.access&Opcodes.ACC_ABSTRACT)!=0)return mapMethodName(owner,name,method.desc);}catch(Exception ignored){}return name;}public String map(String x){return c.getOrDefault(x,x);}public String mapFieldName(String o,String n,String d){String v=find(o,n,f,new HashSet<>());return v==null?n:v;}public String mapMethodName(String o,String n,String d){if(n.startsWith("<"))return n;String v=find(o,n+d,m,new HashSet<>());return v==null?n:v;}};
 try(JarOutputStream out=new JarOutputStream(Files.newOutputStream(Path.of(a[2])))){for(var e:nodes.entrySet()){ClassWriter w=new ClassWriter(0);e.getValue().accept(new ClassRemapper(w,r));out.putNextEntry(new JarEntry(r.map(e.getKey())+".class"));out.write(w.toByteArray());out.closeEntry();}}System.out.println("Remapped "+nodes.size()+" classes");
 }
}
